test('issueInvoice assigns sequential numbers', () => {
  const invoiceResult1 = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1 }],
  });
  const invoice1 = invoiceResult1.value;

  const invoiceResult2 = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-02-15',
    lines: [{ sku: firstProduct.sku, qty: 2 }],
  });
  const invoice2 = invoiceResult2.value;

  const result1 = issueInvoice(invoice1, []);
